<?php
require_once "inc/config.php"; require_once "inc/admin_auth.php"; require_admin_permission($pdo,'payments');
$status=(string)($_GET['status']??'');$q=trim((string)($_GET['q']??''));$where=[];$p=[];if(in_array($status,['initiated','paid','failed','refunded'],true)){$where[]='p.status=?';$p[]=$status;}if($q!==''){$where[]='(CAST(p.id AS CHAR)=? OR CAST(p.order_id AS CHAR)=? OR c.full_name LIKE ? OR p.provider_payment_id LIKE ?)';$like="%$q%";array_push($p,$q,$q,$like,$like);}
$sql="SELECT p.id,p.order_id,p.cust_id,p.provider,p.provider_payment_id,p.amount,p.currency,p.status,p.paid_at,p.created_at,c.full_name FROM payments p JOIN customers c ON c.id=p.cust_id";if($where)$sql.=" WHERE ".implode(' AND ',$where);$sql.=" ORDER BY p.id DESC LIMIT 100";$stmt=$pdo->prepare($sql);$stmt->execute($p);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="az"><head><?php include "inc/head.php"; ?></head><body><div class="app-main"><div id="app-wrapper" class="app-wrapper d-flex flex-column align-items-stretch min-vh-100"><?php include "inc/sidebar.php"; ?><?php include "inc/navbar.php"; ?><div class="app-content-wrapper py-13"><div class="container-fluid"><div class="page-header pb-7 d-flex justify-content-between align-items-center"><div><h2 class="fw-semibold fs-7">Ödənişlər</h2><div class="text-muted">Provider nəticələri yalnız oxunur; manual status dəyişimi yoxdur.</div></div><a class="btn btn-outline-primary" href="api/management/export.php?type=payments">CSV export</a></div><form class="row g-3 mb-5"><div class="col-md-5"><input class="form-control" name="q" value="<?=admin_h($q)?>" placeholder="Payment, order, vendor, provider ID"></div><div class="col-md-5"><select class="form-control" name="status"><option value="">Bütün statuslar</option><?php foreach(['initiated','paid','failed','refunded'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filtr</button></div></form><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body table-responsive"><table class="table"><tr><th>ID</th><th>Vendor</th><th>Order</th><th>Provider</th><th>Məbləğ</th><th>Status</th><th>Tarix</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=admin_h($r['full_name'])?></td><td>#<?=$r['order_id']?></td><td><?=admin_h($r['provider'])?> / <?=admin_h($r['provider_payment_id'])?></td><td><?=admin_h($r['amount'].' '.$r['currency'])?></td><td><?=admin_h($r['status'])?></td><td><?=admin_h($r['created_at'])?></td></tr><?php endforeach;?></table></div></div></div></div><?php include "inc/footer.php"; ?></div></div><?php include "inc/scripts_url.php"; ?></body></html>
